   131→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
   132→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
   133→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
   134→
   135→	if opts.IsIncremental {
   136→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
   137→	}
   138→	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
   139→}
