   262→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
   263→// Returns the absolute file paths from the git tree root for the sessions map.
   264→func (s *GitStore) writeSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
   265→	filePaths := SessionFilePaths{}
   266→
   267→	// Write transcript
   268→	if err := s.writeTranscript(opts, sessionPath, entries); err != nil {
   269→		return filePaths, err
   270→	}
   271→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
   272→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
   273→
   274→	// Write prompts
   275→	if len(opts.Prompts) > 0 {
   276→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   277→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   278→		if err != nil {
   279→			return filePaths, err
   280→		}
   281→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
   282→			Name: sessionPath + paths.PromptFileName,
   283→			Mode: filemode.Regular,
   284→			Hash: blobHash,
   285→		}
   286→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
   287→	}
   288→
   289→	// Write context
   290→	if len(opts.Context) > 0 {
   291→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   292→		if err != nil {
   293→			return filePaths, err
   294→		}
   295→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
   296→			Name: sessionPath + paths.ContextFileName,
   297→			Mode: filemode.Regular,
   298→			Hash: blobHash,
   299→		}
   300→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
   301→	}
   302→
   303→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
   304→	sessionMetadata := CommittedMetadata{
   305→		CheckpointID:                opts.CheckpointID,
   306→		SessionID:                   opts.SessionID,
   307→		Strategy:                    opts.Strategy,
   308→		CreatedAt:                   time.Now().UTC(),
   309→		Branch:                      opts.Branch,
   310→		CheckpointsCount:            opts.CheckpointsCount,
   311→		FilesTouched:                opts.FilesTouched,
   312→		Agent:                       opts.Agent,
   313→		IsTask:                      opts.IsTask,
   314→		ToolUseID:                   opts.ToolUseID,
   315→		SessionCount:                1, // Session-level always 1
   316→		SessionIDs:                  []string{opts.SessionID},
   317→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
   318→		TranscriptLinesAtStart:      opts.TranscriptLinesAtStart,
   319→		TokenUsage:                  opts.TokenUsage,
   320→		InitialAttribution:          opts.InitialAttribution,
   321→	}
   322→
   323→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
   324→	if err != nil {
   325→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
   326→	}
   327→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   328→	if err != nil {
   329→		return filePaths, err
   330→	}
   331→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
   332→		Name: sessionPath + paths.MetadataFileName,
   333→		Mode: filemode.Regular,
   334→		Hash: metadataHash,
   335→	}
   336→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
   337→
   338→	return filePaths, nil
   339→}
