   341→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
   342→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
   343→	summary := CheckpointSummary{
   344→		CheckpointID:     opts.CheckpointID,
   345→		Strategy:         opts.Strategy,
   346→		Branch:           opts.Branch,
   347→		CheckpointsCount: opts.CheckpointsCount,
   348→		FilesTouched:     opts.FilesTouched,
   349→		Sessions:         []SessionFilePaths{sessionFilePaths},
   350→		TokenUsage:       opts.TokenUsage,
   351→	}
   352→
   353→	// Aggregate with existing summary if present
   354→	if existingSummary != nil {
   355→		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
   356→		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
   357→		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)
   358→
   359→		// Copy existing sessions and append new session
   360→		summary.Sessions = make([]SessionFilePaths, len(existingSummary.Sessions)+1)
   361→		copy(summary.Sessions, existingSummary.Sessions)
   362→		summary.Sessions[len(existingSummary.Sessions)] = sessionFilePaths
   363→	}
   364→
   365→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   366→	if err != nil {
   367→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   368→	}
   369→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   370→	if err != nil {
   371→		return err
   372→	}
   373→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   374→		Name: basePath + paths.MetadataFileName,
   375→		Mode: filemode.Regular,
   376→		Hash: metadataHash,
   377→	}
   378→	return nil
   379→}
