   381→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   382→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   383→	blob, err := repo.BlobObject(hash)
   384→	if err != nil {
   385→		return nil, fmt.Errorf("failed to get blob: %w", err)
   386→	}
   387→
   388→	reader, err := blob.Reader()
   389→	if err != nil {
   390→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   391→	}
   392→	defer reader.Close()
   393→
   394→	var result T
   395→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   396→		return nil, fmt.Errorf("failed to decode: %w", err)
   397→	}
   398→
   399→	return &result, nil
   400→}
