   407→// aggregateTokenUsage sums two TokenUsage structs.
   408→// Returns nil if both inputs are nil.
   409→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   410→	if a == nil && b == nil {
   411→		return nil
   412→	}
   413→	result := &agent.TokenUsage{}
   414→	if a != nil {
   415→		result.InputTokens = a.InputTokens
   416→		result.CacheCreationTokens = a.CacheCreationTokens
   417→		result.CacheReadTokens = a.CacheReadTokens
   418→		result.OutputTokens = a.OutputTokens
   419→		result.APICallCount = a.APICallCount
   420→	}
   421→	if b != nil {
   422→		result.InputTokens += b.InputTokens
   423→		result.CacheCreationTokens += b.CacheCreationTokens
   424→		result.CacheReadTokens += b.CacheReadTokens
   425→		result.OutputTokens += b.OutputTokens
   426→		result.APICallCount += b.APICallCount
   427→	}
   428→	return result
   429→}
