   431→// writeTranscript writes the transcript file from in-memory content or file path.
   432→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   433→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   434→	transcript := opts.Transcript
   435→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   436→		var readErr error
   437→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   438→		if readErr != nil {
   439→			// Non-fatal: transcript may not exist yet
   440→			transcript = nil
   441→		}
   442→	}
   443→	if len(transcript) == 0 {
   444→		return nil
   445→	}
   446→
   447→	// Chunk the transcript if it's too large
   448→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   449→	if err != nil {
   450→		return fmt.Errorf("failed to chunk transcript: %w", err)
   451→	}
   452→
   453→	// Write chunk files
   454→	for i, chunk := range chunks {
   455→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   456→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   457→		if err != nil {
   458→			return err
   459→		}
   460→		entries[chunkPath] = object.TreeEntry{
   461→			Name: chunkPath,
   462→			Mode: filemode.Regular,
   463→			Hash: blobHash,
   464→		}
   465→	}
   466→
   467→	// Content hash for deduplication (hash of full transcript)
   468→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   469→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   470→	if err != nil {
   471→		return err
   472→	}
   473→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   474→		Name: basePath + paths.ContentHashFileName,
   475→		Mode: filemode.Regular,
   476→		Hash: hashBlob,
   477→	}
   478→	return nil
   479→}
