   481→// mergeFilesTouched combines two file lists, removing duplicates.
   482→func mergeFilesTouched(existing, additional []string) []string {
   483→	seen := make(map[string]bool)
   484→	var result []string
   485→
   486→	for _, f := range existing {
   487→		if !seen[f] {
   488→			seen[f] = true
   489→			result = append(result, f)
   490→		}
   491→	}
   492→	for _, f := range additional {
   493→		if !seen[f] {
   494→			seen[f] = true
   495→			result = append(result, f)
   496→		}
   497→	}
   498→
   499→	sort.Strings(result)
   500→	return result
   501→}
