   508→// archiveExistingSession moves existing session files to a numbered subfolder.
   509→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   510→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   511→	// Determine archive folder number
   512→	sessionCount := existingMetadata.SessionCount
   513→	if sessionCount == 0 {
   514→		sessionCount = 1 // backwards compat
   515→	}
   516→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   517→
   518→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   519→	filesToArchive := []string{
   520→		paths.MetadataFileName,
   521→		paths.TranscriptFileName,
   522→		paths.PromptFileName,
   523→		paths.ContextFileName,
   524→		paths.ContentHashFileName,
   525→	}
   526→
   527→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   528→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   529→	for srcPath := range entries {
   530→		if strings.HasPrefix(srcPath, chunkPrefix) {
   531→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   532→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   533→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   534→			}
   535→		}
   536→	}
   537→
   538→	// Move each file to archive folder
   539→	for _, filename := range filesToArchive {
   540→		srcPath := basePath + filename
   541→		if entry, exists := entries[srcPath]; exists {
   542→			// Add to archive location
   543→			dstPath := archivePath + filename
   544→			entries[dstPath] = object.TreeEntry{
   545→				Name: dstPath,
   546→				Mode: entry.Mode,
   547→				Hash: entry.Hash,
   548→			}
   549→			// Remove from original location (will be overwritten by new session)
   550→			delete(entries, srcPath)
   551→		}
   552→	}
   553→}
