   555→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   556→// Returns sessions ordered by folder index (oldest first).
   557→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   558→	var archived []ArchivedSession
   559→
   560→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   561→	// The most recent session is at the root level (not archived).
   562→	// Session count N means there are N-1 archived sessions.
   563→	for i := 1; i < sessionCount; i++ {
   564→		folderName := strconv.Itoa(i)
   565→
   566→		// Try to get the archived session subtree
   567→		subTree, err := checkpointTree.Tree(folderName)
   568→		if err != nil {
   569→			continue // Folder doesn't exist, skip
   570→		}
   571→
   572→		session := ArchivedSession{
   573→			FolderIndex: i,
   574→		}
   575→
   576→		// Read metadata to get session ID
   577→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   578→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   579→				var metadata CommittedMetadata
   580→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   581→					session.SessionID = metadata.SessionID
   582→				}
   583→			}
   584→		}
   585→
   586→		// Read transcript (handles both chunked and non-chunked formats)
   587→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   588→			session.Transcript = transcript
   589→		}
   590→
   591→		// Read prompts
   592→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   593→			if content, contentErr := file.Contents(); contentErr == nil {
   594→				session.Prompts = content
   595→			}
   596→		}
   597→
   598→		// Only add if we got a transcript
   599→		if len(session.Transcript) > 0 {
   600→			archived = append(archived, session)
   601→		}
   602→	}
   603→
   604→	return archived
   605→}
