   607→// buildCommitMessage constructs the commit message with proper trailers.
   608→// The commit subject is always "Checkpoint: <id>" for consistency.
   609→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   610→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   611→	var commitMsg strings.Builder
   612→
   613→	// Subject line is always the checkpoint ID for consistent formatting
   614→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   615→
   616→	// Include custom description in body if provided (e.g., task checkpoint details)
   617→	if opts.CommitSubject != "" {
   618→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   619→	}
   620→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   621→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   622→	if opts.Agent != "" {
   623→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   624→	}
   625→	if opts.EphemeralBranch != "" {
   626→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   627→	}
   628→	if taskMetadataPath != "" {
   629→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   630→	}
   631→
   632→	return commitMsg.String()
   633→}
