   653→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   654→// Returns nil, nil if the checkpoint doesn't exist.
   655→//
   656→// The storage format uses numbered subdirectories for each session (1-based):
   657→//
   658→//	<checkpoint-id>/
   659→//	├── metadata.json      # CheckpointSummary with sessions map
   660→//	├── 1/                 # First session
   661→//	│   ├── metadata.json  # Session-specific metadata
   662→//	│   └── full.jsonl     # Transcript
   663→//	├── 2/                 # Second session
   664→//	└── ...
   665→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   666→	_ = ctx // Reserved for future use
   667→
   668→	tree, err := s.getSessionsBranchTree()
   669→	if err != nil {
   670→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   671→	}
   672→
   673→	checkpointPath := checkpointID.Path()
   674→	checkpointTree, err := tree.Tree(checkpointPath)
   675→	if err != nil {
   676→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   677→	}
   678→
   679→	result := &ReadCommittedResult{}
   680→
   681→	// Read root metadata.json as CheckpointSummary
   682→	var summary CheckpointSummary
   683→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   684→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   685→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   686→			json.Unmarshal([]byte(content), &summary)
   687→		}
   688→	}
   689→
   690→	// Convert CheckpointSummary to CommittedMetadata for backwards compatibility
   691→	// Note: Agent, SessionID, SessionCount, and SessionIDs are derived from session-level metadata
   692→	result.Metadata = CommittedMetadata{
   693→		CheckpointID:     summary.CheckpointID,
   694→		Strategy:         summary.Strategy,
   695→		Branch:           summary.Branch,
   696→		CheckpointsCount: summary.CheckpointsCount,
   697→		FilesTouched:     summary.FilesTouched,
   698→		SessionCount:     len(summary.Sessions),
   699→		TokenUsage:       summary.TokenUsage,
   700→	}
   701→
   702→	// Read data from the appropriate session subdirectories
   703→	if len(summary.Sessions) > 0 {
   704→		// Find the latest session index (highest numbered directory, 1-based)
   705→		latestIndex := len(summary.Sessions)
   706→
   707→		// Read latest session data
   708→		latestDir := strconv.Itoa(latestIndex)
   709→		if latestTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   710→			// Get agent type and session info from session-specific metadata
   711→			var agentType agent.AgentType
   712→			if sessionMetadataFile, fileErr := latestTree.File(paths.MetadataFileName); fileErr == nil {
   713→				if content, contentErr := sessionMetadataFile.Contents(); contentErr == nil {
   714→					var sessionMetadata CommittedMetadata
   715→					if jsonErr := json.Unmarshal([]byte(content), &sessionMetadata); jsonErr == nil {
   716→						agentType = sessionMetadata.Agent
   717→						// Set fields derived from session metadata
   718→						result.Metadata.Agent = sessionMetadata.Agent
   719→						result.Metadata.SessionID = sessionMetadata.SessionID
   720→						result.Metadata.CreatedAt = sessionMetadata.CreatedAt
   721→					}
   722→				}
   723→			}
   724→
   725→			// Read transcript
   726→			if transcript, transcriptErr := readTranscriptFromTree(latestTree, agentType); transcriptErr == nil && transcript != nil {
   727→				result.Transcript = transcript
   728→			}
   729→
   730→			// Read prompts
   731→			if file, fileErr := latestTree.File(paths.PromptFileName); fileErr == nil {
   732→				if content, contentErr := file.Contents(); contentErr == nil {
   733→					result.Prompts = content
   734→				}
   735→			}
   736→
   737→			// Read context
   738→			if file, fileErr := latestTree.File(paths.ContextFileName); fileErr == nil {
   739→				if content, contentErr := file.Contents(); contentErr == nil {
   740→					result.Context = content
   741→				}
   742→			}
   743→		}
   744→
   745→		// Read archived sessions (all except the latest)
   746→		result.ArchivedSessions = s.readArchivedSessionsFromSummary(checkpointTree, summary)
   747→	}
   748→
   749→	return result, nil
   750→}
