   752→// readArchivedSessionsFromSummary reads transcript data from archived session subdirectories using the sessions array.
   753→// Returns sessions ordered by folder index (oldest first), excluding the latest session.
   754→func (s *GitStore) readArchivedSessionsFromSummary(checkpointTree *object.Tree, summary CheckpointSummary) []ArchivedSession {
   755→	var archived []ArchivedSession
   756→
   757→	// Iterate through all sessions except the latest (1-based indexing)
   758→	// Sessions are in folders 1, 2, ..., N where N is the latest
   759→	sessionCount := len(summary.Sessions)
   760→	for i := 1; i < sessionCount; i++ {
   761→		folderName := strconv.Itoa(i)
   762→
   763→		// Try to get the session subtree
   764→		subTree, err := checkpointTree.Tree(folderName)
   765→		if err != nil {
   766→			continue // Folder doesn't exist, skip
   767→		}
   768→
   769→		session := ArchivedSession{
   770→			FolderIndex: i,
   771→		}
   772→
   773→		// Get agent type from session metadata
   774→		var agentType agent.AgentType
   775→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   776→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   777→				var metadata CommittedMetadata
   778→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   779→					session.SessionID = metadata.SessionID
   780→					agentType = metadata.Agent
   781→				}
   782→			}
   783→		}
   784→
   785→		// Read transcript (handles both chunked and non-chunked formats)
   786→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   787→			session.Transcript = transcript
   788→		}
   789→
   790→		// Read prompts
   791→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   792→			if content, contentErr := file.Contents(); contentErr == nil {
   793→				session.Prompts = content
   794→			}
   795→		}
   796→
   797→		// Only add if we got a transcript
   798→		if len(session.Transcript) > 0 {
   799→			archived = append(archived, session)
   800→		}
   801→	}
   802→
   803→	return archived
   804→}
