   806→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   807→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   808→//
   809→
   810→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   811→	_ = ctx // Reserved for future use
   812→
   813→	tree, err := s.getSessionsBranchTree()
   814→	if err != nil {
   815→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   816→	}
   817→
   818→	var checkpoints []CommittedInfo
   819→
   820→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   821→	for _, bucketEntry := range tree.Entries {
   822→		if bucketEntry.Mode != filemode.Dir {
   823→			continue
   824→		}
   825→		// Bucket should be 2 hex chars
   826→		if len(bucketEntry.Name) != 2 {
   827→			continue
   828→		}
   829→
   830→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   831→		if treeErr != nil {
   832→			continue
   833→		}
   834→
   835→		// Each entry in the bucket is the remaining part of the checkpoint ID
   836→		for _, checkpointEntry := range bucketTree.Entries {
   837→			if checkpointEntry.Mode != filemode.Dir {
   838→				continue
   839→			}
   840→
   841→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   842→			if cpTreeErr != nil {
   843→				continue
   844→			}
   845→
   846→			// Reconstruct checkpoint ID: <bucket><remaining>
   847→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   848→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   849→			if cpIDErr != nil {
   850→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   851→				continue
   852→			}
   853→
   854→			info := CommittedInfo{
   855→				CheckpointID: checkpointID,
   856→			}
   857→
   858→			// Get details from root metadata file (CheckpointSummary format)
   859→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   860→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   861→					var summary CheckpointSummary
   862→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
   863→						info.CheckpointsCount = summary.CheckpointsCount
   864→						info.FilesTouched = summary.FilesTouched
   865→						info.SessionCount = len(summary.Sessions)
   866→
   867→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
   868→						if len(summary.Sessions) > 0 {
   869→							latestIndex := len(summary.Sessions)
   870→							latestDir := strconv.Itoa(latestIndex)
   871→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   872→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
   873→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
   874→										var sessionMetadata CommittedMetadata
   875→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   876→											info.Agent = sessionMetadata.Agent
   877→											info.SessionID = sessionMetadata.SessionID
   878→											info.CreatedAt = sessionMetadata.CreatedAt
   879→										}
   880→									}
   881→								}
   882→							}
   883→						}
   884→					}
   885→				}
   886→			}
   887→
   888→			checkpoints = append(checkpoints, info)
   889→		}
   890→	}
   891→
   892→	// Sort by time (most recent first)
   893→	sort.Slice(checkpoints, func(i, j int) bool {
   894→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   895→	})
   896→
   897→	return checkpoints, nil
   898→}
