   947→// UpdateSummary updates the summary field in the latest session's metadata.
   948→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   949→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   950→	_ = ctx // Reserved for future use
   951→
   952→	// Ensure sessions branch exists
   953→	if err := s.ensureSessionsBranch(); err != nil {
   954→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   955→	}
   956→
   957→	// Get current branch tip and flatten tree
   958→	ref, entries, err := s.getSessionsBranchEntries()
   959→	if err != nil {
   960→		return err
   961→	}
   962→
   963→	// Read root CheckpointSummary to find the latest session
   964→	basePath := checkpointID.Path() + "/"
   965→	rootMetadataPath := basePath + paths.MetadataFileName
   966→	entry, exists := entries[rootMetadataPath]
   967→	if !exists {
   968→		return ErrCheckpointNotFound
   969→	}
   970→
   971→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
   972→	if err != nil {
   973→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
   974→	}
   975→
   976→	// Find the latest session's metadata path (1-based indexing)
   977→	latestIndex := len(checkpointSummary.Sessions)
   978→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
   979→	sessionEntry, exists := entries[sessionMetadataPath]
   980→	if !exists {
   981→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
   982→	}
   983→
   984→	// Read and update session metadata
   985→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
   986→	if err != nil {
   987→		return fmt.Errorf("failed to read session metadata: %w", err)
   988→	}
   989→
   990→	// Update the summary
   991→	existingMetadata.Summary = summary
   992→
   993→	// Write updated session metadata
   994→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   995→	if err != nil {
   996→		return fmt.Errorf("failed to marshal metadata: %w", err)
   997→	}
   998→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   999→	if err != nil {
  1000→		return fmt.Errorf("failed to create metadata blob: %w", err)
  1001→	}
  1002→	entries[sessionMetadataPath] = object.TreeEntry{
  1003→		Name: sessionMetadataPath,
  1004→		Mode: filemode.Regular,
  1005→		Hash: metadataHash,
  1006→	}
  1007→
  1008→	// Build and commit
  1009→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
  1010→	if err != nil {
  1011→		return err
  1012→	}
  1013→
  1014→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1015→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
  1016→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
  1017→	if err != nil {
  1018→		return err
  1019→	}
  1020→
  1021→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1022→	newRef := plumbing.NewHashReference(refName, newCommitHash)
  1023→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1024→		return fmt.Errorf("failed to set branch reference: %w", err)
  1025→	}
  1026→
  1027→	return nil
  1028→}
