  1030→// ensureSessionsBranch ensures the entire/sessions branch exists.
  1031→func (s *GitStore) ensureSessionsBranch() error {
  1032→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1033→	_, err := s.repo.Reference(refName, true)
  1034→	if err == nil {
  1035→		return nil // Branch exists
  1036→	}
  1037→
  1038→	// Create orphan branch with empty tree
  1039→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
  1040→	if err != nil {
  1041→		return err
  1042→	}
  1043→
  1044→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
  1045→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
  1046→	if err != nil {
  1047→		return err
  1048→	}
  1049→
  1050→	newRef := plumbing.NewHashReference(refName, commitHash)
  1051→	if err := s.repo.Storer.SetReference(newRef); err != nil {
  1052→		return fmt.Errorf("failed to set branch reference: %w", err)
  1053→	}
  1054→	return nil
  1055→}
  1056→
  1057→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
  1058→// Falls back to origin/entire/sessions if the local branch doesn't exist.
  1059→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
  1060→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1061→	ref, err := s.repo.Reference(refName, true)
  1062→	if err != nil {
  1063→		// Local branch doesn't exist, try remote-tracking branch
  1064→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
  1065→		ref, err = s.repo.Reference(remoteRefName, true)
  1066→		if err != nil {
  1067→			return nil, fmt.Errorf("sessions branch not found: %w", err)
  1068→		}
  1069→	}
  1070→
  1071→	commit, err := s.repo.CommitObject(ref.Hash())
  1072→	if err != nil {
  1073→		return nil, fmt.Errorf("failed to get commit object: %w", err)
  1074→	}
  1075→
  1076→	tree, err := commit.Tree()
  1077→	if err != nil {
  1078→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
  1079→	}
  1080→
  1081→	return tree, nil
  1082→}
