  1084→// CreateBlobFromContent creates a blob object from in-memory content.
  1085→// Exported for use by strategy package (session_test.go)
  1086→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1087→	obj := repo.Storer.NewEncodedObject()
  1088→	obj.SetType(plumbing.BlobObject)
  1089→	obj.SetSize(int64(len(content)))
  1090→
  1091→	writer, err := obj.Writer()
  1092→	if err != nil {
  1093→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1094→	}
  1095→
  1096→	_, err = writer.Write(content)
  1097→	if err != nil {
  1098→		_ = writer.Close()
  1099→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1100→	}
  1101→	if err := writer.Close(); err != nil {
  1102→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1103→	}
  1104→
  1105→	hash, err := repo.Storer.SetEncodedObject(obj)
  1106→	if err != nil {
  1107→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1108→	}
  1109→	return hash, nil
  1110→}
