  1112→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1113→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1114→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1115→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1116→		if err != nil {
  1117→			return err
  1118→		}
  1119→		if info.IsDir() {
  1120→			return nil
  1121→		}
  1122→
  1123→		// Skip symlinks to prevent reading files outside the metadata directory.
  1124→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1125→		// then be captured in the checkpoint and stored in git history.
  1126→		if info.Mode()&os.ModeSymlink != 0 {
  1127→			return nil
  1128→		}
  1129→
  1130→		// Get relative path within metadata dir
  1131→		relPath, err := filepath.Rel(metadataDir, path)
  1132→		if err != nil {
  1133→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1134→		}
  1135→
  1136→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1137→		if strings.HasPrefix(relPath, "..") {
  1138→			return fmt.Errorf("path traversal detected: %s", relPath)
  1139→		}
  1140→
  1141→		// Create blob from file
  1142→		blobHash, mode, err := createBlobFromFile(s.repo, path)
  1143→		if err != nil {
  1144→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1145→		}
  1146→
  1147→		// Store at checkpoint path
  1148→		fullPath := basePath + relPath
  1149→		entries[fullPath] = object.TreeEntry{
  1150→			Name: fullPath,
  1151→			Mode: mode,
  1152→			Hash: blobHash,
  1153→		}
  1154→
  1155→		return nil
  1156→	})
  1157→	if err != nil {
  1158→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1159→	}
  1160→	return nil
  1161→}
