  1183→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1184→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1185→// The agentType is used for reassembling chunks in the correct format.
  1186→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1187→	// Collect all transcript-related files
  1188→	var chunkFiles []string
  1189→	var hasBaseFile bool
  1190→
  1191→	for _, entry := range tree.Entries {
  1192→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1193→			hasBaseFile = true
  1194→		}
  1195→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1196→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1197→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1198→			if idx > 0 {
  1199→				chunkFiles = append(chunkFiles, entry.Name)
  1200→			}
  1201→		}
  1202→	}
  1203→
  1204→	// If we have chunk files, read and reassemble them
  1205→	if len(chunkFiles) > 0 {
  1206→		// Sort chunk files by index
  1207→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1208→
  1209→		// Check if base file should be included as chunk 0.
  1210→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1211→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1212→		if hasBaseFile {
  1213→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1214→		}
  1215→
  1216→		var chunks [][]byte
  1217→		for _, chunkFile := range chunkFiles {
  1218→			file, err := tree.File(chunkFile)
  1219→			if err != nil {
  1220→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1221→					slog.String("chunk_file", chunkFile),
  1222→					slog.String("error", err.Error()),
  1223→				)
  1224→				continue
  1225→			}
  1226→			content, err := file.Contents()
  1227→			if err != nil {
  1228→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1229→					slog.String("chunk_file", chunkFile),
  1230→					slog.String("error", err.Error()),
  1231→				)
  1232→				continue
  1233→			}
  1234→			chunks = append(chunks, []byte(content))
  1235→		}
  1236→
  1237→		if len(chunks) > 0 {
  1238→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1239→			if err != nil {
  1240→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1241→			}
  1242→			return result, nil
  1243→		}
  1244→	}
  1245→
  1246→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1247→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1248→		if content, err := file.Contents(); err == nil {
  1249→			return []byte(content), nil
  1250→		}
  1251→	}
  1252→
  1253→	// Try legacy filename
  1254→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1255→		if content, err := file.Contents(); err == nil {
  1256→			return []byte(content), nil
  1257→		}
  1258→	}
  1259→
  1260→	return nil, nil
  1261→}
