   198→// ensureMetadataBranch creates the orphan entire/sessions branch if it doesn't exist.
   199→// This branch has no parent and starts with an empty tree.
   200→func EnsureMetadataBranch(repo *git.Repository) error {
   201→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   202→
   203→	// Check if branch already exists
   204→	_, err := repo.Reference(refName, true)
   205→	if err == nil {
   206→		// Branch already exists
   207→		return nil
   208→	}
   209→
   210→	// Create empty tree (no files)
   211→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
   212→	obj := repo.Storer.NewEncodedObject()
   213→	if err := emptyTree.Encode(obj); err != nil {
   214→		return fmt.Errorf("failed to encode empty tree: %w", err)
   215→	}
   216→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
   217→	if err != nil {
   218→		return fmt.Errorf("failed to store empty tree: %w", err)
   219→	}
   220→
   221→	// Create orphan commit (no parent)
   222→	now := time.Now()
   223→	sig := object.Signature{
   224→		Name:  "Entire",
   225→		Email: "entire@local",
   226→		When:  now,
   227→	}
   228→
   229→	commit := &object.Commit{
   230→		TreeHash:  emptyTreeHash,
   231→		Author:    sig,
   232→		Committer: sig,
   233→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata for the auto-commit strategy.\n",
   234→	}
   235→	// Note: No ParentHashes - this is an orphan commit
   236→
   237→	commitObj := repo.Storer.NewEncodedObject()
   238→	if err := commit.Encode(commitObj); err != nil {
   239→		return fmt.Errorf("failed to encode orphan commit: %w", err)
   240→	}
   241→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   242→	if err != nil {
   243→		return fmt.Errorf("failed to store orphan commit: %w", err)
   244→	}
   245→
   246→	// Create branch reference
   247→	ref := plumbing.NewHashReference(refName, commitHash)
   248→	if err := repo.Storer.SetReference(ref); err != nil {
   249→		return fmt.Errorf("failed to create metadata branch: %w", err)
   250→	}
   251→
   252→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
   253→	return nil
   254→}
