   344→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
   345→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
   346→// Returns empty string if no valid prompt is found.
   347→func ExtractFirstPrompt(content string) string {
   348→	if content == "" {
   349→		return ""
   350→	}
   351→
   352→	// Prompts are separated by "\n\n---\n\n"
   353→	// Find the first non-empty prompt
   354→	prompts := strings.Split(content, "\n\n---\n\n")
   355→	var firstPrompt string
   356→	for _, p := range prompts {
   357→		cleaned := strings.TrimSpace(p)
   358→		// Skip empty prompts or prompts that are just dashes/separators
   359→		if cleaned == "" || isOnlySeparators(cleaned) {
   360→			continue
   361→		}
   362→		firstPrompt = cleaned
   363→		break
   364→	}
   365→
   366→	if firstPrompt == "" {
   367→		return ""
   368→	}
   369→
   370→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
   371→}
