   390→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
   391→func isOnlySeparators(s string) bool {
   392→	for _, r := range s {
   393→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
   394→			return false
   395→		}
   396→	}
   397→	return true
   398→}
