   400→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
   401→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
   402→// For single-session checkpoints, returns a slice with just the root prompt.
   403→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
   404→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
   405→		// Single session - just return the root prompt
   406→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
   407→		if prompt != "" {
   408→			return []string{prompt}
   409→		}
   410→		return nil
   411→	}
   412→
   413→	// Multi-session: read prompts from archived folders (1/, 2/, etc.) and root
   414→	prompts := make([]string, len(sessionIDs))
   415→
   416→	// Read archived session prompts (folders 1, 2, ... N-1)
   417→	for i := 1; i < sessionCount; i++ {
   418→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
   419→		prompts[i-1] = ReadSessionPromptFromTree(tree, archivedPath)
   420→	}
   421→
   422→	// Read the most recent session prompt (at root level)
   423→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
   424→
   425→	return prompts
   426→}
