   473→// OpenRepository opens the git repository with linked worktree support enabled.
   474→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
   475→// which is required for proper operation in git worktrees created via 'git worktree add'.
   476→//
   477→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
   478→// - Commits appear to succeed but are not persisted
   479→// - Refs are written to incorrect locations
   480→// - The worktree's HEAD/index don't get updated properly
   481→//
   482→// This happens because worktrees use .git as a file (pointing to the main repo)
   483→// rather than a directory, and go-git needs to route paths correctly between
   484→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
   485→//
   486→// The function first uses 'git rev-parse --show-toplevel' to find the repository
   487→// root, which works correctly even when called from a subdirectory within the repo.
   488→func OpenRepository() (*git.Repository, error) {
   489→	// First, find the repository root using git rev-parse --show-toplevel
   490→	// This works correctly from any subdirectory within the repository
   491→	repoRoot, err := GetWorktreePath()
   492→	if err != nil {
   493→		// Fallback to current directory if git command fails
   494→		// (e.g., if git is not installed or we're not in a repo)
   495→		repoRoot = "."
   496→	}
   497→
   498→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
   499→		EnableDotGitCommonDir: true,
   500→	})
   501→	if err != nil {
   502→		return nil, fmt.Errorf("failed to open repository: %w", err)
   503→	}
   504→	return repo, nil
   505→}
   506→
   507→// IsInsideWorktree returns true if the current directory is inside a git worktree
   508→// (as opposed to the main repository). Worktrees have .git as a file pointing
   509→// to the main repo, while the main repo has .git as a directory.
   510→// This function works correctly from any subdirectory within the repository.
   511→func IsInsideWorktree() bool {
   512→	// First find the repository root
   513→	repoRoot, err := GetWorktreePath()
   514→	if err != nil {
   515→		return false
   516→	}
   517→
   518→	gitPath := filepath.Join(repoRoot, gitDir)
   519→	gitInfo, err := os.Stat(gitPath)
   520→	if err != nil {
   521→		return false
   522→	}
   523→	return !gitInfo.IsDir()
   524→}
   525→
   526→// GetMainRepoRoot returns the root directory of the main repository.
   527→// In the main repo, this is the worktree path (repo root).
   528→// In a worktree, this parses the .git file to find the main repo.
   529→// This function works correctly from any subdirectory within the repository.
   530→//
   531→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
   532→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
   533→// See: https://git-scm.com/docs/gitrepository-layout
   534→func GetMainRepoRoot() (string, error) {
   535→	// First find the worktree/repo root
   536→	repoRoot, err := GetWorktreePath()
   537→	if err != nil {
   538→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   539→	}
   540→
   541→	if !IsInsideWorktree() {
   542→		return repoRoot, nil
   543→	}
   544→
   545→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
   546→	gitFilePath := filepath.Join(repoRoot, gitDir)
   547→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
   548→	if err != nil {
   549→		return "", fmt.Errorf("failed to read .git file: %w", err)
   550→	}
   551→
   552→	gitdir := strings.TrimSpace(string(content))
   553→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
   554→
   555→	// Extract main repo root: everything before "/.git/"
   556→	idx := strings.LastIndex(gitdir, "/.git/")
   557→	if idx < 0 {
   558→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
   559→	}
   560→	return gitdir[:idx], nil
   561→}
   562→
   563→// GetGitCommonDir returns the path to the shared git directory.
   564→// In a regular checkout, this is .git/
   565→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   566→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
   567→func GetGitCommonDir() (string, error) {
   568→	ctx := context.Background()
   569→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   570→	cmd.Dir = "."
   571→	output, err := cmd.Output()
   572→	if err != nil {
   573→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   574→	}
   575→
   576→	commonDir := strings.TrimSpace(string(output))
   577→
   578→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   579→	// so we need to make it absolute if it isn't already
   580→	if !filepath.IsAbs(commonDir) {
   581→		commonDir = filepath.Join(".", commonDir)
   582→	}
   583→
   584→	return filepath.Clean(commonDir), nil
   585→}
