   587→// GetWorktreePath returns the absolute path to the current worktree root.
   588→// This is the working directory path, not the git directory.
   589→func GetWorktreePath() (string, error) {
   590→	ctx := context.Background()
   591→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
   592→	output, err := cmd.Output()
   593→	if err != nil {
   594→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   595→	}
   596→	return strings.TrimSpace(string(output)), nil
   597→}
