   599→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
   600→// Works correctly from any subdirectory within the repository.
   601→func EnsureEntireGitignore() error {
   602→	// Get absolute path for the gitignore file
   603→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
   604→	if err != nil {
   605→		gitignoreAbs = entireGitignore // Fallback to relative
   606→	}
   607→
   608→	// Read existing content
   609→	var content string
   610→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
   611→		content = string(data)
   612→	}
   613→
   614→	// All entries that should be in .entire/.gitignore
   615→	requiredEntries := []string{
   616→		"tmp/",
   617→		"settings.local.json",
   618→		"metadata/",
   619→		"current_session",
   620→		"logs/",
   621→	}
   622→
   623→	// Track what needs to be added
   624→	var toAdd []string
   625→	for _, entry := range requiredEntries {
   626→		if !strings.Contains(content, entry) {
   627→			toAdd = append(toAdd, entry)
   628→		}
   629→	}
   630→
   631→	// Nothing to add
   632→	if len(toAdd) == 0 {
   633→		return nil
   634→	}
   635→
   636→	// Ensure .entire directory exists
   637→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
   638→		return fmt.Errorf("failed to create .entire directory: %w", err)
   639→	}
   640→
   641→	// Append missing entries to gitignore
   642→	var sb strings.Builder
   643→	for _, entry := range toAdd {
   644→		sb.WriteString(entry + "\n")
   645→	}
   646→	content += sb.String()
   647→
   648→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
   649→		return fmt.Errorf("failed to write gitignore: %w", err)
   650→	}
   651→	return nil
   652→}
