   654→// checkCanRewind checks if working directory is clean enough for rewind.
   655→// Returns (canRewind, reason, error). Shared by shadow and linear-shadow strategies.
   656→func checkCanRewind() (bool, string, error) {
   657→	repo, err := OpenRepository()
   658→	if err != nil {
   659→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
   660→	}
   661→
   662→	worktree, err := repo.Worktree()
   663→	if err != nil {
   664→		return false, "", fmt.Errorf("failed to get worktree: %w", err)
   665→	}
   666→
   667→	status, err := worktree.Status()
   668→	if err != nil {
   669→		return false, "", fmt.Errorf("failed to get status: %w", err)
   670→	}
   671→
   672→	if status.IsClean() {
   673→		return true, "", nil
   674→	}
   675→
   676→	var modified, added, deleted []string
   677→	for file, st := range status {
   678→		// Skip .entire directory
   679→		if paths.IsInfrastructurePath(file) {
   680→			continue
   681→		}
   682→
   683→		// Skip untracked files
   684→		if st.Worktree == git.Untracked {
   685→			continue
   686→		}
   687→
   688→		switch {
   689→		case st.Staging == git.Added || st.Worktree == git.Added:
   690→			added = append(added, file)
   691→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   692→			deleted = append(deleted, file)
   693→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   694→			modified = append(modified, file)
   695→		}
   696→	}
   697→
   698→	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
   699→		return true, "", nil
   700→	}
   701→
   702→	var msg strings.Builder
   703→	msg.WriteString("You have uncommitted changes:\n")
   704→	for _, f := range modified {
   705→		msg.WriteString(fmt.Sprintf("  modified:   %s\n", f))
   706→	}
   707→	for _, f := range added {
   708→		msg.WriteString(fmt.Sprintf("  added:      %s\n", f))
   709→	}
   710→	for _, f := range deleted {
   711→		msg.WriteString(fmt.Sprintf("  deleted:    %s\n", f))
   712→	}
   713→	msg.WriteString("\nPlease commit or stash your changes before rewinding.")
   714→
   715→	return false, msg.String(), nil
   716→}
   717→
   718→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
   719→// Unlike checkCanRewind, this always returns canRewind=true but includes a warning message
   720→// with +/- line stats for uncommitted changes. Used by manual-commit strategy.
   721→func checkCanRewindWithWarning() (bool, string, error) {
   722→	repo, err := OpenRepository()
   723→	if err != nil {
   724→		// Can't open repo - still allow rewind but without stats
   725→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
   726→	}
   727→
   728→	worktree, err := repo.Worktree()
   729→	if err != nil {
   730→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
   731→	}
   732→
   733→	status, err := worktree.Status()
   734→	if err != nil {
   735→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
   736→	}
   737→
   738→	if status.IsClean() {
   739→		return true, "", nil
   740→	}
   741→
   742→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
   743→	head, err := repo.Head()
   744→	if err != nil {
   745→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
   746→	}
   747→
   748→	headCommit, err := repo.CommitObject(head.Hash())
   749→	if err != nil {
   750→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
   751→	}
   752→
   753→	headTree, err := headCommit.Tree()
   754→	if err != nil {
   755→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
   756→	}
   757→
   758→	type fileChange struct {
   759→		status   string // "modified", "added", "deleted"
   760→		added    int
   761→		removed  int
   762→		filename string
   763→	}
   764→
   765→	var changes []fileChange
   766→	// Use repo root, not cwd - git status returns paths relative to repo root
   767→	repoRoot, err := GetWorktreePath()
   768→	if err != nil {
   769→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo root lookup fails
   770→	}
   771→
   772→	for file, st := range status {
   773→		// Skip .entire directory
   774→		if paths.IsInfrastructurePath(file) {
   775→			continue
   776→		}
   777→
   778→		// Skip untracked files
   779→		if st.Worktree == git.Untracked {
   780→			continue
   781→		}
   782→
   783→		var change fileChange
   784→		change.filename = file
   785→
   786→		switch {
   787→		case st.Staging == git.Added || st.Worktree == git.Added:
   788→			change.status = "added"
   789→			// New file - count all lines as added
   790→			absPath := filepath.Join(repoRoot, file)
   791→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   792→				change.added = countLines(content)
   793→			}
   794→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   795→			change.status = "deleted"
   796→			// Deleted file - count lines from HEAD as removed
   797→			if entry, err := headTree.File(file); err == nil {
   798→				if content, err := entry.Contents(); err == nil {
   799→					change.removed = countLines([]byte(content))
   800→				}
   801→			}
   802→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   803→			change.status = "modified"
   804→			// Modified file - compute diff stats
   805→			var headContent, workContent []byte
   806→			if entry, err := headTree.File(file); err == nil {
   807→				if content, err := entry.Contents(); err == nil {
   808→					headContent = []byte(content)
   809→				}
   810→			}
   811→			absPath := filepath.Join(repoRoot, file)
   812→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   813→				workContent = content
   814→			}
   815→			if headContent != nil && workContent != nil {
   816→				change.added, change.removed = computeDiffStats(headContent, workContent)
   817→			}
   818→		default:
   819→			continue
   820→		}
   821→
   822→		changes = append(changes, change)
   823→	}
   824→
   825→	if len(changes) == 0 {
   826→		return true, "", nil
   827→	}
   828→
   829→	// Sort changes by filename for consistent output
   830→	sort.Slice(changes, func(i, j int) bool {
   831→		return changes[i].filename < changes[j].filename
   832→	})
   833→
   834→	var msg strings.Builder
   835→	msg.WriteString("The following uncommitted changes will be reverted:\n")
   836→
   837→	totalAdded, totalRemoved := 0, 0
   838→	for _, c := range changes {
   839→		totalAdded += c.added
   840→		totalRemoved += c.removed
   841→
   842→		var stats string
   843→		switch {
   844→		case c.added > 0 && c.removed > 0:
   845→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
   846→		case c.added > 0:
   847→			stats = fmt.Sprintf("+%d", c.added)
   848→		case c.removed > 0:
   849→			stats = fmt.Sprintf("-%d", c.removed)
   850→		}
   851→
   852→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
   853→		if stats != "" {
   854→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
   855→		}
   856→		msg.WriteString("\n")
   857→	}
   858→
   859→	if totalAdded > 0 || totalRemoved > 0 {
   860→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
   861→	}
   862→
   863→	return true, msg.String(), nil
   864→}
   865→
   866→// countLines counts the number of lines in content.
   867→func countLines(content []byte) int {
   868→	if len(content) == 0 {
   869→		return 0
   870→	}
   871→	count := 1
   872→	for _, b := range content {
   873→		if b == '\n' {
   874→			count++
   875→		}
   876→	}
   877→	// Don't count trailing newline as extra line
   878→	if len(content) > 0 && content[len(content)-1] == '\n' {
   879→		count--
   880→	}
   881→	return count
   882→}
   883→
   884→// computeDiffStats computes added and removed line counts between old and new content.
   885→// Uses a simple line-based diff algorithm.
   886→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
   887→	oldLines := splitLines(oldContent)
   888→	newLines := splitLines(newContent)
   889→
   890→	// Build a set of old lines with counts
   891→	oldSet := make(map[string]int)
   892→	for _, line := range oldLines {
   893→		oldSet[line]++
   894→	}
   895→
   896→	// Check which new lines are truly new
   897→	for _, line := range newLines {
   898→		if oldSet[line] > 0 {
   899→			oldSet[line]--
   900→		} else {
   901→			added++
   902→		}
   903→	}
   904→
   905→	// Remaining old lines are removed
   906→	for _, count := range oldSet {
   907→		removed += count
   908→	}
   909→
   910→	return added, removed
   911→}
   912→
   913→// splitLines splits content into lines, preserving empty lines.
   914→func splitLines(content []byte) []string {
   915→	if len(content) == 0 {
   916→		return nil
   917→	}
   918→	s := string(content)
   919→	// Remove trailing newline to avoid empty last element
   920→	s = strings.TrimSuffix(s, "\n")
   921→	return strings.Split(s, "\n")
   922→}
