   930→// StageFilesContext describes what type of staging operation this is (for messages).
   931→type StageFilesContext string
   932→
   933→const (
   934→	// StageForSession is used when staging files for a session checkpoint.
   935→	StageForSession StageFilesContext = "session"
   936→	// StageForTask is used when staging files for a task checkpoint.
   937→	StageForTask StageFilesContext = "task"
   938→)
   939→
   940→// StageFiles stages modified, new, and deleted files to the git worktree.
   941→//
   942→// This function handles three categories of file changes:
   943→//  1. Modified files: existing files that have been changed
   944→//  2. New files: files that were created during the session
   945→//  3. Deleted files: files that were removed during the session
   946→//
   947→// Error Handling Strategy:
   948→//   - Individual file staging errors are logged to stderr but don't fail the operation
   949→//   - This ensures that partial staging succeeds even if some files have issues
   950→//   - If a modified file no longer exists, it's treated as a deletion
   951→//
   952→// The stageCtx parameter is used for user-facing messages to indicate whether
   953→// this is staging for a session checkpoint or a task checkpoint.
   954→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
   955→	// Get repo root for resolving file paths
   956→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
   957→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
   958→	// fileExists() could return false for existing files, causing worktree.Remove()
   959→	// to incorrectly delete them.
   960→	repoRoot := worktree.Filesystem.Root()
   961→
   962→	// Stage modified files
   963→	for _, file := range modified {
   964→		// Resolve path relative to repo root for existence check
   965→		absPath := filepath.Join(repoRoot, file)
   966→		if fileExists(absPath) {
   967→			if _, err := worktree.Add(file); err != nil {
   968→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   969→			} else {
   970→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
   971→			}
   972→		} else {
   973→			// File was deleted - stage the deletion
   974→			if _, err := worktree.Remove(file); err != nil {
   975→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
   976→			}
   977→		}
   978→	}
   979→
   980→	// Stage new files
   981→	if len(newFiles) > 0 {
   982→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
   983→		for _, file := range newFiles {
   984→			if _, err := worktree.Add(file); err != nil {
   985→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   986→			} else {
   987→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
   988→			}
   989→		}
   990→	}
   991→
   992→	// Stage deleted files
   993→	for _, file := range deleted {
   994→		if _, err := worktree.Remove(file); err != nil {
   995→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
   996→		} else {
   997→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
   998→		}
   999→	}
  1000→}
