  1091→// HardResetWithProtection performs a git reset --hard to the specified commit.
  1092→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1093→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1094→// Returns the short commit ID (7 chars) on success for display purposes.
  1095→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
  1096→	ctx := context.Background()
  1097→	hashStr := commitHash.String()
  1098→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
  1099→	if output, err := cmd.CombinedOutput(); err != nil {
  1100→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1101→	}
  1102→
  1103→	// Return short commit ID for display
  1104→	shortID = hashStr
  1105→	if len(shortID) > 7 {
  1106→		shortID = shortID[:7]
  1107→	}
  1108→	return shortID, nil
  1109→}
