  1111→// collectUntrackedFiles collects all untracked files in the working directory.
  1112→// This is used to capture the initial state when starting a session,
  1113→// ensuring untracked files present at session start are preserved during rewind.
  1114→// Excludes .git/, .entire/, and .claude/ directories (which are system/config directories).
  1115→// Works correctly from any subdirectory within the repository.
  1116→func collectUntrackedFiles() ([]string, error) {
  1117→	// Get repository root to walk from there
  1118→	repoRoot, err := GetWorktreePath()
  1119→	if err != nil {
  1120→		repoRoot = "." // Fallback to current directory
  1121→	}
  1122→
  1123→	var untrackedFiles []string
  1124→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
  1125→		if walkErr != nil {
  1126→			return nil //nolint:nilerr // Skip filesystem errors during walk
  1127→		}
  1128→
  1129→		// Get path relative to repo root
  1130→		relPath, err := filepath.Rel(repoRoot, path)
  1131→		if err != nil {
  1132→			return nil //nolint:nilerr // Skip paths we can't make relative
  1133→		}
  1134→
  1135→		// Skip directories
  1136→		if info.IsDir() {
  1137→			// Skip .git, .claude, and .entire directories
  1138→			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
  1139→				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1140→				return filepath.SkipDir
  1141→			}
  1142→			return nil
  1143→		}
  1144→
  1145→		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
  1146→		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1147→			return nil
  1148→		}
  1149→
  1150→		untrackedFiles = append(untrackedFiles, relPath)
  1151→		return nil
  1152→	})
  1153→	if err != nil {
  1154→		return nil, fmt.Errorf("failed to walk directory: %w", err)
  1155→	}
  1156→
  1157→	return untrackedFiles, nil
  1158→}
