  1160→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
  1161→// It checks the Entire-Session trailer first, then falls back to extracting from
  1162→// the metadata directory path in the Entire-Metadata trailer.
  1163→// Returns empty string if no session ID is found.
  1164→func ExtractSessionIDFromCommit(commit *object.Commit) string {
  1165→	// Try Entire-Session trailer first
  1166→	if sessionID, found := trailers.ParseSession(commit.Message); found {
  1167→		return sessionID
  1168→	}
  1169→
  1170→	// Try extracting from metadata directory (last path component)
  1171→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
  1172→		return filepath.Base(metadataDir)
  1173→	}
  1174→
  1175→	return ""
  1176→}
