  1187→// createCommit creates a commit object
  1188→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
  1189→	now := time.Now()
  1190→	sig := object.Signature{
  1191→		Name:  authorName,
  1192→		Email: authorEmail,
  1193→		When:  now,
  1194→	}
  1195→
  1196→	commit := &object.Commit{
  1197→		TreeHash:  treeHash,
  1198→		Author:    sig,
  1199→		Committer: sig,
  1200→		Message:   message,
  1201→	}
  1202→
  1203→	// Add parent if not a new branch
  1204→	if parentHash != plumbing.ZeroHash {
  1205→		commit.ParentHashes = []plumbing.Hash{parentHash}
  1206→	}
  1207→
  1208→	obj := repo.Storer.NewEncodedObject()
  1209→	if err := commit.Encode(obj); err != nil {
  1210→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
  1211→	}
  1212→
  1213→	hash, err := repo.Storer.SetEncodedObject(obj)
  1214→	if err != nil {
  1215→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
  1216→	}
  1217→
  1218→	return hash, nil
  1219→}
