  1221→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1222→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1223→//
  1224→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1225→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1226→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
  1227→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1228→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1229→	// Helper to read first line from a file in tree
  1230→	readFirstLine := func(path string) string {
  1231→		file, err := tree.File(path)
  1232→		if err != nil {
  1233→			return ""
  1234→		}
  1235→		content, err := file.Contents()
  1236→		if err != nil {
  1237→			return ""
  1238→		}
  1239→		lines := strings.SplitN(content, "\n", 2)
  1240→		if len(lines) > 0 && lines[0] != "" {
  1241→			desc := strings.TrimSpace(lines[0])
  1242→			// Remove markdown header prefix if present
  1243→			return strings.TrimPrefix(desc, "# ")
  1244→		}
  1245→		return ""
  1246→	}
  1247→
  1248→	// If metadataDir is provided, look there directly
  1249→	if metadataDir != "" {
  1250→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1251→			return desc
  1252→		}
  1253→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1254→			return desc
  1255→		}
  1256→		return NoDescription
  1257→	}
  1258→
  1259→	// No metadataDir provided - first try looking at the root of the tree
  1260→	// (used when the tree is already the session directory)
  1261→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1262→		return desc
  1263→	}
  1264→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1265→		return desc
  1266→	}
  1267→
  1268→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1269→	// (used when the tree is the full worktree)
  1270→	var desc string
  1271→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1272→	_ = tree.Files().ForEach(func(f *object.File) error {
  1273→		if desc != "" {
  1274→			return nil // Already found description
  1275→		}
  1276→		name := f.Name
  1277→		if strings.Contains(name, ".entire/metadata/") {
  1278→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1279→				content, err := f.Contents()
  1280→				if err != nil {
  1281→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1282→				}
  1283→				lines := strings.SplitN(content, "\n", 2)
  1284→				if len(lines) > 0 && lines[0] != "" {
  1285→					desc = strings.TrimSpace(lines[0])
  1286→					desc = strings.TrimPrefix(desc, "# ")
  1287→				}
  1288→			}
  1289→		}
  1290→		return nil
  1291→	})
  1292→
  1293→	if desc != "" {
  1294→		return desc
  1295→	}
  1296→	return NoDescription
  1297→}
