  1299→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1300→// It checks local config first, then falls back to global config.
  1301→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
  1302→// operations to proceed even without git user config, which is especially useful
  1303→// for internal metadata commits on branches like entire/sessions.
  1304→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1305→	// Get repository config (includes local settings)
  1306→	cfg, err := repo.Config()
  1307→	if err == nil {
  1308→		name = cfg.User.Name
  1309→		email = cfg.User.Email
  1310→	}
  1311→
  1312→	// If not found in local config, try global config
  1313→	if name == "" || email == "" {
  1314→		globalCfg, err := config.LoadConfig(config.GlobalScope)
  1315→		if err == nil {
  1316→			if name == "" {
  1317→				name = globalCfg.User.Name
  1318→			}
  1319→			if email == "" {
  1320→				email = globalCfg.User.Email
  1321→			}
  1322→		}
  1323→	}
  1324→
  1325→	// Provide sensible defaults if git user is not configured
  1326→	if name == "" {
  1327→		name = "Unknown"
  1328→	}
  1329→	if email == "" {
  1330→		email = "unknown@local"
  1331→	}
  1332→
  1333→	return name, email
  1334→}
