  1336→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
  1337→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
  1338→// This is used to capture branch metadata for checkpoints.
  1339→func GetCurrentBranchName(repo *git.Repository) string {
  1340→	head, err := repo.Head()
  1341→	if err != nil || !head.Name().IsBranch() {
  1342→		return ""
  1343→	}
  1344→	return head.Name().Short()
  1345→}
