  1347→// getMainBranchHash returns the hash of the main branch (main or master).
  1348→// Returns ZeroHash if no main branch is found.
  1349→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
  1350→	// Try common main branch names
  1351→	for _, branchName := range []string{branchMain, branchMaster} {
  1352→		// Try local branch first
  1353→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
  1354→		if err == nil {
  1355→			return ref.Hash()
  1356→		}
  1357→		// Try remote tracking branch
  1358→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
  1359→		if err == nil {
  1360→			return ref.Hash()
  1361→		}
  1362→	}
  1363→	return plumbing.ZeroHash
  1364→}
