  1366→// GetDefaultBranchName returns the name of the default branch.
  1367→// First checks origin/HEAD, then falls back to checking if main/master exists.
  1368→// Returns empty string if unable to determine.
  1369→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1370→func GetDefaultBranchName(repo *git.Repository) string {
  1371→	// Try to get the symbolic reference for origin/HEAD
  1372→	// Use resolved=false to get the symbolic ref itself, then extract its target
  1373→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
  1374→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
  1375→		target := ref.Target().String()
  1376→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
  1377→			return branchName
  1378→		}
  1379→	}
  1380→
  1381→	// Fallback: check if origin/main or origin/master exists
  1382→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
  1383→		return branchMain
  1384→	}
  1385→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
  1386→		return branchMaster
  1387→	}
  1388→
  1389→	// Final fallback: check local branches
  1390→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
  1391→		return branchMain
  1392→	}
  1393→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
  1394→		return branchMaster
  1395→	}
  1396→
  1397→	return ""
  1398→}
