  1400→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
  1401→// Returns (isOnDefault, currentBranchName).
  1402→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1403→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
  1404→	currentBranch := GetCurrentBranchName(repo)
  1405→	if currentBranch == "" {
  1406→		return false, ""
  1407→	}
  1408→
  1409→	defaultBranch := GetDefaultBranchName(repo)
  1410→	if defaultBranch == "" {
  1411→		// Can't determine default, check common names
  1412→		if currentBranch == branchMain || currentBranch == branchMaster {
  1413→			return true, currentBranch
  1414→		}
  1415→		return false, currentBranch
  1416→	}
  1417→
  1418→	return currentBranch == defaultBranch, currentBranch
  1419→}
