   220→// readCheckpointMetadata reads checkpoint metadata from the metadata branch.
   221→// It reads the root CheckpointSummary and converts it to CommittedMetadata for compatibility.
   222→// To get session-specific fields (like Agent), it also reads from the latest session's metadata.
   223→func readCheckpointMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) CommittedMetadata {
   224→	t.Helper()
   225→
   226→	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
   227→	if err != nil {
   228→		t.Fatalf("failed to get metadata branch reference: %v", err)
   229→	}
   230→
   231→	commit, err := repo.CommitObject(ref.Hash())
   232→	if err != nil {
   233→		t.Fatalf("failed to get commit object: %v", err)
   234→	}
   235→
   236→	tree, err := commit.Tree()
   237→	if err != nil {
   238→		t.Fatalf("failed to get tree: %v", err)
   239→	}
   240→
   241→	checkpointTree, err := tree.Tree(checkpointID.Path())
   242→	if err != nil {
   243→		t.Fatalf("failed to get checkpoint tree: %v", err)
   244→	}
   245→
   246→	// Read root metadata.json as CheckpointSummary
   247→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
   248→	if err != nil {
   249→		t.Fatalf("failed to find metadata.json: %v", err)
   250→	}
   251→
   252→	content, err := metadataFile.Contents()
   253→	if err != nil {
   254→		t.Fatalf("failed to read metadata.json: %v", err)
   255→	}
   256→
   257→	var summary CheckpointSummary
   258→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
   259→		t.Fatalf("failed to parse metadata.json as CheckpointSummary: %v", err)
   260→	}
   261→
   262→	// Convert CheckpointSummary to CommittedMetadata
   263→	// Note: SessionCount and SessionIDs are derived from session-level metadata
   264→	metadata := CommittedMetadata{
   265→		CheckpointID:     summary.CheckpointID,
   266→		Strategy:         summary.Strategy,
   267→		Branch:           summary.Branch,
   268→		CheckpointsCount: summary.CheckpointsCount,
   269→		FilesTouched:     summary.FilesTouched,
   270→		SessionCount:     len(summary.Sessions),
   271→		TokenUsage:       summary.TokenUsage,
   272→	}
   273→
   274→	// Read session-level metadata to get Agent, SessionID, CreatedAt, SessionIDs (1-based indexing)
   275→	if len(summary.Sessions) > 0 {
   276→		latestIndex := len(summary.Sessions)
   277→		sessionDir := strconv.Itoa(latestIndex)
   278→		sessionTree, err := checkpointTree.Tree(sessionDir)
   279→		if err == nil {
   280→			if sessionFile, err := sessionTree.File(paths.MetadataFileName); err == nil {
   281→				if sessionContent, err := sessionFile.Contents(); err == nil {
   282→					var sessionMetadata CommittedMetadata
   283→					if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   284→						metadata.Agent = sessionMetadata.Agent
   285→						metadata.SessionID = sessionMetadata.SessionID
   286→						metadata.CreatedAt = sessionMetadata.CreatedAt
   287→					}
   288→				}
   289→			}
   290→		}
   291→
   292→		// Read all session IDs (1-based indexing: 1, 2, 3, ...)
   293→		var sessionIDs []string
   294→		for i := 1; i <= len(summary.Sessions); i++ {
   295→			sessionSubDir := strconv.Itoa(i)
   296→			if subTree, err := checkpointTree.Tree(sessionSubDir); err == nil {
   297→				if sessionFile, err := subTree.File(paths.MetadataFileName); err == nil {
   298→					if sessionContent, err := sessionFile.Contents(); err == nil {
   299→						var sessionMetadata CommittedMetadata
   300→						if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   301→							sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
   302→							// Also get agents for the Agents array
   303→							if sessionMetadata.Agent != "" {
   304→								found := false
   305→								for _, a := range metadata.Agents {
   306→									if a == sessionMetadata.Agent {
   307→										found = true
   308→										break
   309→									}
   310→								}
   311→								if !found {
   312→									metadata.Agents = append(metadata.Agents, sessionMetadata.Agent)
   313→								}
   314→							}
   315→						}
   316→					}
   317→				}
   318→			}
   319→		}
   320→		metadata.SessionIDs = sessionIDs
   321→	}
   322→
   323→	return metadata
   324→}
