   512→// TestWriteTemporary_Deduplication verifies that WriteTemporary skips creating
   513→// a new commit when the tree hash matches the previous checkpoint.
   514→func TestWriteTemporary_Deduplication(t *testing.T) {
   515→	tempDir := t.TempDir()
   516→
   517→	// Initialize a git repository with an initial commit
   518→	repo, err := git.PlainInit(tempDir, false)
   519→	if err != nil {
   520→		t.Fatalf("failed to init git repo: %v", err)
   521→	}
   522→
   523→	// Create worktree and make initial commit
   524→	worktree, err := repo.Worktree()
   525→	if err != nil {
   526→		t.Fatalf("failed to get worktree: %v", err)
   527→	}
   528→
   529→	readmeFile := filepath.Join(tempDir, "README.md")
   530→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
   531→		t.Fatalf("failed to write README: %v", err)
   532→	}
   533→	if _, err := worktree.Add("README.md"); err != nil {
   534→		t.Fatalf("failed to add README: %v", err)
   535→	}
   536→	initialCommit, err := worktree.Commit("Initial commit", &git.CommitOptions{
   537→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   538→	})
   539→	if err != nil {
   540→		t.Fatalf("failed to commit: %v", err)
   541→	}
   542→
   543→	// Change to temp dir so paths.RepoRoot() works correctly
   544→	t.Chdir(tempDir)
   545→
   546→	// Create a test file that will be included in checkpoints
   547→	testFile := filepath.Join(tempDir, "test.go")
   548→	if err := os.WriteFile(testFile, []byte("package main\n"), 0o644); err != nil {
   549→		t.Fatalf("failed to write test file: %v", err)
   550→	}
   551→
   552→	// Create metadata directory
   553→	metadataDir := filepath.Join(tempDir, ".entire", "metadata", "test-session")
   554→	if err := os.MkdirAll(metadataDir, 0o755); err != nil {
   555→		t.Fatalf("failed to create metadata dir: %v", err)
   556→	}
   557→	if err := os.WriteFile(filepath.Join(metadataDir, "full.jsonl"), []byte(`{"test": true}`), 0o644); err != nil {
   558→		t.Fatalf("failed to write transcript: %v", err)
   559→	}
   560→
   561→	// Create checkpoint store
   562→	store := NewGitStore(repo)
   563→
   564→	// First checkpoint should be created
   565→	baseCommit := initialCommit.String()
   566→	result1, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   567→		SessionID:         "test-session",
   568→		BaseCommit:        baseCommit,
   569→		ModifiedFiles:     []string{"test.go"},
   570→		MetadataDir:       ".entire/metadata/test-session",
   571→		MetadataDirAbs:    metadataDir,
   572→		CommitMessage:     "Checkpoint 1",
   573→		AuthorName:        "Test",
   574→		AuthorEmail:       "test@test.com",
   575→		IsFirstCheckpoint: true,
   576→	})
   577→	if err != nil {
   578→		t.Fatalf("WriteTemporary() first call error = %v", err)
   579→	}
   580→	if result1.Skipped {
   581→		t.Error("first checkpoint should not be skipped")
   582→	}
   583→	if result1.CommitHash == plumbing.ZeroHash {
   584→		t.Error("first checkpoint should have a commit hash")
   585→	}
   586→
   587→	// Second checkpoint with identical content should be skipped
   588→	result2, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   589→		SessionID:         "test-session",
   590→		BaseCommit:        baseCommit,
   591→		ModifiedFiles:     []string{"test.go"},
   592→		MetadataDir:       ".entire/metadata/test-session",
   593→		MetadataDirAbs:    metadataDir,
   594→		CommitMessage:     "Checkpoint 2",
   595→		AuthorName:        "Test",
   596→		AuthorEmail:       "test@test.com",
   597→		IsFirstCheckpoint: false,
   598→	})
   599→	if err != nil {
   600→		t.Fatalf("WriteTemporary() second call error = %v", err)
   601→	}
   602→	if !result2.Skipped {
   603→		t.Error("second checkpoint with identical content should be skipped")
   604→	}
   605→	if result2.CommitHash != result1.CommitHash {
   606→		t.Errorf("skipped checkpoint should return previous commit hash, got %s, want %s",
   607→			result2.CommitHash, result1.CommitHash)
   608→	}
   609→
   610→	// Modify the file and create another checkpoint - should NOT be skipped
