   960→// TestListCommitted_FallsBackToRemote verifies that ListCommitted can find
   961→// checkpoints when only origin/entire/sessions exists (simulating post-clone state).
   962→func TestListCommitted_FallsBackToRemote(t *testing.T) {
   963→	// Create "remote" repo (non-bare, so we can make commits)
   964→	remoteDir := t.TempDir()
   965→	remoteRepo, err := git.PlainInit(remoteDir, false)
   966→	if err != nil {
   967→		t.Fatalf("failed to init remote repo: %v", err)
   968→	}
   969→
   970→	// Create an initial commit on main branch (required for cloning)
   971→	remoteWorktree, err := remoteRepo.Worktree()
   972→	if err != nil {
   973→		t.Fatalf("failed to get remote worktree: %v", err)
   974→	}
   975→	readmeFile := filepath.Join(remoteDir, "README.md")
   976→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
   977→		t.Fatalf("failed to write README: %v", err)
   978→	}
   979→	if _, err := remoteWorktree.Add("README.md"); err != nil {
   980→		t.Fatalf("failed to add README: %v", err)
   981→	}
   982→	if _, err := remoteWorktree.Commit("Initial commit", &git.CommitOptions{
   983→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   984→	}); err != nil {
   985→		t.Fatalf("failed to create initial commit: %v", err)
   986→	}
   987→
   988→	// Create entire/sessions branch on the remote with a checkpoint
   989→	remoteStore := NewGitStore(remoteRepo)
   990→	cpID := id.MustCheckpointID("abcdef123456")
   991→	err = remoteStore.WriteCommitted(context.Background(), WriteCommittedOptions{
   992→		CheckpointID: cpID,
   993→		SessionID:    "test-session-id",
   994→		Strategy:     "manual-commit",
   995→		Transcript:   []byte(`{"test": true}`),
   996→		AuthorName:   "Test",
   997→		AuthorEmail:  "test@test.com",
   998→	})
   999→	if err != nil {
  1000→		t.Fatalf("failed to write checkpoint to remote: %v", err)
  1001→	}
  1002→
  1003→	// Clone the repo (this clones main, but not entire/sessions by default)
  1004→	localDir := t.TempDir()
  1005→	localRepo, err := git.PlainClone(localDir, false, &git.CloneOptions{
  1006→		URL: remoteDir,
  1007→	})
  1008→	if err != nil {
  1009→		t.Fatalf("failed to clone repo: %v", err)
  1010→	}
  1011→
  1012→	// Fetch the entire/sessions branch to origin/entire/sessions
  1013→	// (but don't create local branch - simulating post-clone state)
  1014→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", paths.MetadataBranchName, paths.MetadataBranchName)
  1015→	err = localRepo.Fetch(&git.FetchOptions{
  1016→		RemoteName: "origin",
  1017→		RefSpecs:   []config.RefSpec{config.RefSpec(refSpec)},
  1018→	})
  1019→	if err != nil && !errors.Is(err, git.NoErrAlreadyUpToDate) {
  1020→		t.Fatalf("failed to fetch entire/sessions: %v", err)
  1021→	}
  1022→
  1023→	// Verify local branch doesn't exist
  1024→	_, err = localRepo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
  1025→	if err == nil {
  1026→		t.Fatal("local entire/sessions branch should not exist")
  1027→	}
  1028→
  1029→	// Verify remote-tracking branch exists
  1030→	_, err = localRepo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true)
  1031→	if err != nil {
  1032→		t.Fatalf("origin/entire/sessions should exist: %v", err)
  1033→	}
  1034→
  1035→	// ListCommitted should find the checkpoint by falling back to remote
  1036→	localStore := NewGitStore(localRepo)
  1037→	checkpoints, err := localStore.ListCommitted(context.Background())
  1038→	if err != nil {
  1039→		t.Fatalf("ListCommitted() error = %v", err)
  1040→	}
  1041→	if len(checkpoints) != 1 {
  1042→		t.Errorf("ListCommitted() returned %d checkpoints, want 1", len(checkpoints))
  1043→	}
  1044→	if len(checkpoints) > 0 && checkpoints[0].CheckpointID.String() != cpID.String() {
  1045→		t.Errorf("ListCommitted() checkpoint ID = %q, want %q", checkpoints[0].CheckpointID, cpID)
  1046→	}
  1047→}
